public class Solution {
  /**
   * 答案二分：谓词 fits(share) = Σ min(demand, share) <= capacity 对 share 单调不减（一旦超就永远超）。
   * 搜索区间 [0, maxShare]，用 long 做中点避免 (lo + hi + 1) 在 int 域溢出；
   * 累加提前退出：一旦 need > capacity 就返回 false，避免无谓的 O(n) 走完全程与潜在溢出。
   */
  public static int fairShareUnits(int[] demands, long capacityUnits) {
    if (demands.length == 0 || capacityUnits <= 0) return 0;
    int maxShare = 0;
    for (int d : demands) {
      if (d < 0) throw new IllegalArgumentException("negative demand");
      if (d > maxShare) maxShare = d;
    }
    long lo = 0;
    long hi = maxShare;                     // 水位线不可能超过最大需求：超出部分不会被任何人消耗
    while (lo < hi) {
      long mid = (lo + hi + 1) >>> 1;       // 上取整中点：配合 lo = mid 的收缩方向
      if (fits(demands, capacityUnits, mid)) lo = mid;
      else hi = mid - 1;
    }
    return (int) lo;
  }

  static boolean fits(int[] demands, long capacity, long share) {
    long need = 0L;
    for (int d : demands) {
      need += Math.min((long) d, share);
      if (need > capacity) return false;    // 提前退出：规模大时这是能否过时限的关键
    }
    return true;
  }
}

