public class Solution {
  // 朴素：平均分配 —— 水位线 = capacity / 租户数。
  // 忽略了"小需求租户被截断后腾出的额度"，因此在需求不均的集群上系统性低估水位线，
  // 而在总需求远小于容量时又给出天文数字（超出任何租户的真实需求）。
  public static int fairShareUnits(int[] demands, long capacityUnits) {
    if (demands.length == 0 || capacityUnits <= 0) return 0;
    return (int) (capacityUnits / demands.length);
  }
}
